-- Historical events (SSOT 3.2). One row per event; effects live in child tables so the event list is loaded
-- as data only (generated by tools/generate_sengoku_events.py; see documents/poc/historical-events.md).

CREATE TABLE JAC_HistoricalEvents (
	EventType TEXT NOT NULL PRIMARY KEY,
	Pack TEXT NOT NULL,
	-- Historical year. Converted to a turn by the Lua script from the game speed's calendar (GameSpeed_Turns).
	Year INTEGER,
	-- Month of the year (1-12) as the event list gives it (SSOT 3.2: match the month as far as possible). NULL: month 1.
	Month INTEGER CHECK (Month BETWEEN 1 AND 12),
	-- Explicit turn; wins over Year when both are set.
	Turn INTEGER,
	-- When the year arrives, a target faction with none of the event's prerequisites (JAC_HistoricalEventPrereq*)
	-- gets only this boost (eureka / inspiration), not the research itself. NULL: no boost.
	BoostTech TEXT REFERENCES Technologies(TechnologyType),
	BoostCivic TEXT REFERENCES Civics(CivicType),
	-- Notification title. With House set, only that civilization sees Name; the others see GenericName (SSOT 3.2).
	Name TEXT NOT NULL,
	House TEXT,
	GenericName TEXT,
	-- Notification body; the advisor's line when Advisor is 1.
	Description TEXT NOT NULL,
	-- 1: the human the event happens for also sees the advisor popup with Description (owner decision E5a).
	Advisor BOOLEAN NOT NULL DEFAULT 0,
	-- 0: notify the faction the event happens for. 1: notify every alive major faction.
	NotifyAll BOOLEAN NOT NULL DEFAULT 0,
	CHECK (Year IS NOT NULL OR Turn IS NOT NULL),
	CHECK (BoostTech IS NULL OR BoostCivic IS NULL),
	CHECK ((House IS NULL) = (GenericName IS NULL))
);

-- A target faction that has any one of these techs or civics gets the event's effects (before its year if it
-- researched first). No rows in either table: the event happens for every target in its year.
CREATE TABLE JAC_HistoricalEventPrereqTechs (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	TechnologyType TEXT NOT NULL REFERENCES Technologies(TechnologyType),
	PRIMARY KEY (EventType, TechnologyType)
);

CREATE TABLE JAC_HistoricalEventPrereqCivics (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	CivicType TEXT NOT NULL REFERENCES Civics(CivicType),
	PRIMARY KEY (EventType, CivicType)
);

-- No rows: every alive major faction is a target.
CREATE TABLE JAC_HistoricalEventTargets (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	CivilizationType TEXT NOT NULL,
	PRIMARY KEY (EventType, CivilizationType)
);

-- Player modifiers attached once to the faction the event fires for.
CREATE TABLE JAC_HistoricalEventModifiers (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	ModifierId TEXT NOT NULL REFERENCES Modifiers(ModifierId),
	PRIMARY KEY (EventType, ModifierId)
);

-- Display-name switch (SSOT 3.1). The civilization ID never changes; UI reads the shared name.
CREATE TABLE JAC_HistoricalEventRenames (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	CivilizationType TEXT NOT NULL,
	Name TEXT NOT NULL,
	PRIMARY KEY (EventType, CivilizationType)
);

-- Resources of an event. SiteId is a site of the Japan maps' resources mod (JAC_PoC_JapanMapScale
-- Scripts/JAC_ResourceSites.lua) or of documents/spec/data/japan-map-resources.json.
-- Records only; the event script does not read this table (SSOT 3.2).
-- reveal: the reserved site the resources mod reveals in its own year or on its research; the event boosts that
-- research instead of revealing it. trade_access / ownership: not implemented / not transferred automatically
-- (Q43); OwnerTo is the civilization the ownership would go to.
CREATE TABLE JAC_HistoricalEventResources (
	EventType TEXT NOT NULL REFERENCES JAC_HistoricalEvents(EventType) ON DELETE CASCADE,
	SiteId TEXT NOT NULL,
	Action TEXT NOT NULL DEFAULT 'reveal' CHECK (Action IN ('reveal', 'trade_access', 'ownership')),
	OwnerTo TEXT,
	CHECK ((Action = 'ownership') = (OwnerTo IS NOT NULL)),
	PRIMARY KEY (EventType, SiteId)
);
